const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path'),fs=require('fs');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:1000}});await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);
const counts=await p.evaluate(()=>{const A=DEUTSCH_COURSE_ART,cards=[...new Map(DEUTSCH_ADAPTIVE.stages.flatMap(s=>s.cards).map(c=>[c.id,c])).values()],phrases=cards.filter(c=>c.visual);if(phrases.length!==46)throw Error('Unexpected phrase inventory');for(const c of phrases){const a=A.resolve(c.de,c.ua);if(a?.kind!=='native'||!DEUTSCH_ADAPTIVE.art(c).includes(a.src))throw Error('Generic/missing scene '+c.de+' '+c.ua)}if(A.nativeScenes.length!==84||new Set(A.nativeScenes.map(a=>a.src)).size!==84)throw Error('Incomplete/deduplicated scene matrix');for(const s of A.nativeScenes)if(A.resolve(s.de,s.uas[0]||'')?.scene!==s.id)throw Error('Wrong scene binding '+s.de);if(A.resolve('Sie lernt','Вони вчаться')?.kind==='native')throw Error('Female singular leaked into plural meaning');if(A.resolve('ihr','її / їхній')?.kind==='native')throw Error('Possessive meaning changed');return {cards:cards.length,phrases:phrases.length,scenes:A.nativeScenes.length}});
await p.evaluate(()=>{const audit=document.createElement('div');audit.id='sceneAudit';for(const s of DEUTSCH_COURSE_ART.nativeScenes){const im=document.createElement('img');im.src=s.src;im.width=160;im.height=160;im.style.objectFit='contain';im.alt=s.de;audit.append(im)}document.body.append(audit)});await p.waitForFunction(()=>[...document.querySelectorAll('#sceneAudit img')].every(i=>i.complete&&i.naturalWidth>0));await p.evaluate(()=>document.querySelector('#sceneAudit').remove());
await p.click('#learningTab');for(const width of [320,390,1280]){await p.setViewportSize({width,height:1000});for(const i of [2,3,4,5,6,7]){await p.evaluate(i=>DEUTSCH_JOURNEY.open(i),i);await p.locator('#learningView img').evaluateAll(xs=>xs.forEach(x=>x.loading='eager'));await p.waitForFunction(()=>[...document.querySelectorAll('#learningView img')].every(i=>i.complete&&i.naturalWidth>0));if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Scene overflow '+width);if(await p.locator('.al-study-grid img').count()!==6)throw Error('Not six native lesson scenes');if(width===390&&[3,4,5].includes(i)){fs.mkdirSync('audit-screenshots',{recursive:true});await p.screenshot({path:'audit-screenshots/native-scenes-'+i+'.png',fullPage:true})}}}console.log('PASS native sentence scenes '+JSON.stringify(counts)+', 84 loaded assets, exact meanings, no fallback, 320–1280px');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
